class Solution {
public:
    vector<int> sortJumbled(vector<int>& mapping, vector<int>& nums) {
        int n = nums.size();
        vector<pair<long long, int>> keyed(n);
        for (int i = 0; i < n; i++) {
            long long m = 0;
            int x = nums[i];
            if (x == 0) {
                m = mapping[0];
            } else {
                int digits[16];
                int cnt = 0;
                while (x > 0) {
                    digits[cnt++] = x % 10;
                    x /= 10;
                }
                for (int j = cnt - 1; j >= 0; j--) {
                    m = m * 10 + mapping[digits[j]];
                }
            }
            keyed[i] = {m, i};
        }
        stable_sort(keyed.begin(), keyed.end());
        vector<int> result(n);
        for (int i = 0; i < n; i++) {
            result[i] = nums[keyed[i].second];
        }
        return result;
    }
};
